def compute(vars):
    start_value = vars["v1"]
    end_value = vars["v2"]
    start_year = 2012
    end_year = 2017
    years = end_year - start_year

    if start_value == 0 or years == 0:
        return None

    annualized_return = ((end_value / start_value) ** (1 / years) - 1) * 100
    return {
        "value": annualized_return,
        "trace": {
            "start_value": start_value,
            "end_value": end_value,
            "temporal_scope": (start_year, end_year),
            "years": years,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
